print('sections',len(secs))
for sec in secs:
    sid=sec.get('id','')
    print('\n\n========',sid,'========')
    # print text with some structure: headings and paragraphs
    for el in sec.find_all(['h1','h2','h3','h4','p','li','td','th'],recursive=True):
        txt=' '.join(el.get_text(' ',strip=True).split())
        if not txt: continue
        if el.name in ('h1','h2','h3','h4'):
            print(f'[{el.name}] {txt}')
        elif el.name=='li':
            print(' -',txt)
        elif el.name in ('td','th'):
            print(' |',txt)
        else:
            print(txt)
