        text = path.read_text(encoding="utf-8", errors="replace")
        self.name = path.stem
        self.bpp = int(re.search(r"\.bpp\s*=\s*(\d+)", text).group(1))
        self.line_height = int(re.search(r"\.line_height\s*=\s*(\d+)", text).group(1))
        self.base_line = int(re.search(r"\.base_line\s*=\s*(\d+)", text).group(1))

        bm = re.search(r"glyph_bitmap\[\]\s*=\s*\{(.*?)\n\};", text, re.S)
        if bm is None:
            raise SystemExit(f"glyph_bitmap not found: {path}")
        self.bitmap = bytes(int(h, 16) for h in re.findall(r"0x([0-9A-Fa-f]+)", bm.group(1)))

        gd = re.search(r"glyph_dsc\[\]\s*=\s*\{(.*?)\n\};", text, re.S)
        if gd is None:
            raise SystemExit(f"glyph_dsc not found: {path}")
        rows = re.findall(
            r"\{\.bitmap_index\s*=\s*(\d+),\s*\.adv_w\s*=\s*(\d+),\s*"
            r"\.box_w\s*=\s*(\d+),\s*\.box_h\s*=\s*(\d+),\s*"
            r"\.ofs_x\s*=\s*(-?\d+),\s*\.ofs_y\s*=\s*(-?\d+)\}",
            gd.group(1),
        )
        self.glyphs: list[dict[str, int]] = [
            {"bitmap_index": int(a), "adv_w": int(b), "box_w": int(c), "box_h": int(d), "ofs_x": int(e), "ofs_y": int(f)}
            for a, b, c, d, e, f in rows
        ]

        cm = re.search(r"cmaps\[\]\s*=\s*\{(.*?)\n\};", text, re.S)
        if cm is None:
            raise SystemExit(f"cmaps not found: {path}")
        self.cmap: dict[int, int] = {}
        for entry in re.findall(r"\{(.*?)\}", cm.group(1), re.S):
            rs = int(re.search(r"\.range_start\s*=\s*(\d+)", entry).group(1))
            rl = int(re.search(r"\.range_length\s*=\s*(\d+)", entry).group(1))
            gs = int(re.search(r"\.glyph_id_start\s*=\s*(\d+)", entry).group(1))
            ul = re.search(r"\.unicode_list\s*=\s*(\w+)", entry).group(1)
            ll = int(re.search(r"\.list_length\s*=\s*(\d+)", entry).group(1))
            typ = re.search(r"\.type\s*=\s*(\w+)", entry).group(1)
            if "SPARSE" in typ:
                um = re.search(rf"{ul}\[\]\s*=\s*\{{(.*?)\}};", text, re.S)
                if um is None:
                    raise SystemExit(f"{ul} not found: {path}")
                offsets = [int(x, 16) for x in re.findall(r"0x([0-9A-Fa-f]+)", um.group(1))]
                for i, off in enumerate(offsets[:ll]):
                    self.cmap[rs + off] = gs + i
            else:
                for i in range(rl):
                    self.cmap[rs + i] = gs + i

    def has(self, ch: str) -> bool:
        return ord(ch) in self.cmap

    def advance(self, ch: str) -> float:
        gid = self.cmap.get(ord(ch))
        if gid is None or gid >= len(self.glyphs):
            return 0.0
        return self.glyphs[gid]["adv_w"] / 16.0

    def alpha(self, gid: int) -> bytes:
        g = self.glyphs[gid]
        w, h = g["box_w"], g["box_h"]
        out = bytearray(w * h)
        if not w or not h:
            return bytes(out)
        start = g["bitmap_index"] * 8
        maxv = (1 << self.bpp) - 1
        for i in range(w * h):
            bit = start + i * self.bpp
            byte = self.bitmap[bit // 8]
            shift = 8 - self.bpp - (bit % 8)
            out[i] = ((byte >> shift) & maxv) * 255 // maxv
        return bytes(out)


