from PIL import Image
import numpy as np

def edge_slopes(path):
    im=Image.open(path).convert('L')
    a=np.array(im)
    h,w=a.shape
    xs_left=[]; xs_right=[]; ys=[]
    for y in range(80,h-80,4):
        row=a[y]
        bright=np.where(row>165)[0]
        if len(bright)>w*0.4:
            xs_left.append(bright[0]); xs_right.append(bright[-1]); ys.append(y)
    if len(ys)<20:
        print(path,'not enough'); return
    ys=np.array(ys,float); xl=np.array(xs_left,float); xr=np.array(xs_right,float)
    # robust linear fit x = a*y+b using median of pairwise slopes
    def slopes(xs):
        vals=[]
        for i in range(len(ys)):
            j=min(len(ys)-1,i+40)
            if ys[j]!=ys[i]: vals.append((xs[j]-xs[i])/(ys[j]-ys[i]))
        return np.median(vals)
    al=slopes(xl); ar=slopes(xr)
    print(path, 'left dx/dy=%.5f angle=%.2f deg; right dx/dy=%.5f angle=%.2f deg' % (al, np.degrees(np.arctan(al)), ar, np.degrees(np.arctan(ar))))

for p in ['实拍图2-处理/HelmOne-实拍2-01-主界面.jpg','实拍图2-处理/HelmOne-实拍2-02-骑行.jpg','实拍图2-处理/HelmOne-实拍2-03-骑行数据.jpg','实拍图2-处理/HelmOne-实拍2-04-海拔.jpg','实拍图2-处理/HelmOne-实拍2-05-导航.jpg']:
    edge_slopes(p)
