from PIL import Image
import numpy as np

def bar_tilt(path, xranges):
    im=Image.open(path).convert('RGB'); a=np.array(im).astype(int); h,w,_=a.shape
    r,g,b=a[:,:,0],a[:,:,1],a[:,:,2]
    mx=np.maximum(np.maximum(r,g),b); mn=np.minimum(np.minimum(r,g),b)
    sat=(mx-mn)
    for x0,x1 in xranges:
        xs=[]; ys=[]
        for y in range(50,h-50):
            seg=sat[y,x0:x1]
            idx=np.where(seg>28)[0]
            if len(idx)>1:
                xs.append(x0+idx.mean()); ys.append(y)
        if len(ys)>20:
            ys=np.array(ys,float); xs=np.array(xs,float)
            # robust slope over pairs 20 rows apart
            vals=[]
            for i in range(len(ys)):
                j=min(len(ys)-1,i+20)
                if ys[j]!=ys[i]: vals.append((xs[j]-xs[i])/(ys[j]-ys[i]))
            sl=np.median(vals)
            print(path, (x0,x1), 'n',len(ys),'dx/dy %.5f angle %.2f deg'%(sl,np.degrees(np.arctan(sl))))

for p in ['实拍图2-处理/HelmOne-实拍2-02-骑行.jpg','实拍图2-处理/HelmOne-实拍2-03-骑行数据.jpg']:
    print('==',p)
    bar_tilt(p,[(30,60),(440,480),(120,140),(560,600)])
